/**
 * Turns the service's answer into one readable line in the execution list.
 *
 * The HTTP node never errors, so every outcome arrives here and has to be
 * told apart by status. The three that matter are different things:
 *
 *   501  the bot token is not set - reactions are simply not configured
 *   401  the shared secret does not match between n8n and the service
 *   2xx  it ran; 'signals' is how many reactions were found, which is
 *        legitimately 0 on a day nobody tapped anything
 *
 * Returning a row rather than throwing keeps a missing token out of the
 * error workflow: nothing is broken, a feature is off.
 */
const cfg = $('Config').first().json;

if (!cfg.store_url) {
  return [{ json: { ok: false, state: 'disabled', detail: 'STORE_URL is empty - the store and the sync are both off' } }];
}

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? {};

if (status === 501) {
  return [{ json: { ok: false, state: 'not-configured', detail: 'DISCORD_BOT_TOKEN is unset - reactions need a bot, not the webhook' } }];
}
if (status === 401) {
  return [{ json: { ok: false, state: 'unauthorised', detail: 'RANKER_TOKEN differs between n8n and the ranker' } }];
}
if (status < 200 || status >= 300) {
  return [{ json: { ok: false, state: 'error', status, detail: String(body?.detail ?? 'no detail') } }];
}

// 'cards_checked', not 'cards' - the endpoint names it for what it did.
const cards = Number(body.cards_checked ?? 0);
const signals = Number(body.signals ?? 0);

return [{
  json: {
    ok: true,
    state: 'synced',
    cards,
    signals,
    detail: signals === 0
      ? `read ${cards} cards, nobody has reacted yet`
      : `read ${cards} cards, recorded ${signals} reactions`,
  },
}];
